func (v ValueValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v ValueValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v ValueValue) String() string {
	return "ValueValue"
}

func (v ValueValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var plugins basetypes.ObjectValue

	if v.Plugins.IsNull() {
		plugins = types.ObjectNull(
			PluginsValue{}.AttributeTypes(ctx),
		)
	}

	if v.Plugins.IsUnknown() {
		plugins = types.ObjectUnknown(
			PluginsValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Plugins.IsNull() && !v.Plugins.IsUnknown() {
		plugins = types.ObjectValueMust(
			PluginsValue{}.AttributeTypes(ctx),
			v.Plugins.Attributes(),
		)
	}

	var labelsVal basetypes.MapValue
	switch {
	case v.Labels.IsUnknown():
		labelsVal = types.MapUnknown(types.StringType)
	case v.Labels.IsNull():
		labelsVal = types.MapNull(types.StringType)
	default:
		var d diag.Diagnostics
		labelsVal, d = types.MapValue(types.StringType, v.Labels.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"created_at": basetypes.Int64Type{},
			"desc":       basetypes.StringType{},
			"labels": basetypes.MapType{
				ElemType: types.StringType,
			},
			"plugins": basetypes.ObjectType{
				AttrTypes: PluginsValue{}.AttributeTypes(ctx),
			},
			"updated_at": basetypes.Int64Type{},
			"username":   basetypes.StringType{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"created_at": basetypes.Int64Type{},
		"desc":       basetypes.StringType{},
		"labels": basetypes.MapType{
			ElemType: types.StringType,
		},
		"plugins": basetypes.ObjectType{
			AttrTypes: PluginsValue{}.AttributeTypes(ctx),
		},
		"updated_at": basetypes.Int64Type{},
		"username":   basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"created_at": v.CreatedAt,
			"desc":       v.Desc,
			"labels":     labelsVal,
			"plugins":    plugins,
			"updated_at": v.UpdatedAt,
			"username":   v.Username,
		})

	return objVal, diags
}

func (v ValueValue) Equal(o attr.Value) bool {
	other, ok := o.(ValueValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.CreatedAt.Equal(other.CreatedAt) {
		return false
	}

	if !v.Desc.Equal(other.Desc) {
		return false
	}

	if !v.Labels.Equal(other.Labels) {
		return false
	}

	if !v.Plugins.Equal(other.Plugins) {
		return false
	}

	if !v.UpdatedAt.Equal(other.UpdatedAt) {
		return false
	}

	if !v.Username.Equal(other.Username) {
		return false
	}

	return true
}

func (v ValueValue) Type(ctx context.Context) attr.Type {
	return ValueType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v ValueValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"created_at": basetypes.Int64Type{},
		"desc":       basetypes.StringType{},
		"labels": basetypes.MapType{
			ElemType: types.StringType,
		},
		"plugins": basetypes.ObjectType{
			AttrTypes: PluginsValue{}.AttributeTypes(ctx),
		},
		"updated_at": basetypes.Int64Type{},
		"username":   basetypes.StringType{},
	}
}

